def ref(inp):
    lines = inp.split("\n")
    a = json.loads(lines[0])
    b = json.loads(lines[1])
    # Literal definition: an array with k zeros (and base sum B) can reach total T
    # iff: if k == 0 then T == B; if k > 0 then T - B >= k (each zero gets a positive value).
    def feasible(arr, T):
        k = sum(1 for x in arr if x == 0)
        B = sum(arr)
        if k == 0:
            return T == B
        return T - B >= k
    bound = sum(a) + sum(b) + len(a) + len(b) + 2
    for T in range(0, bound + 1):
        if feasible(a, T) and feasible(b, T):
            return json.dumps(T)
