    # Can the zeros of arr be replaced by positive integers so the array sums to T?
    s = sum(arr)
    z = arr.count(0)
    if z == 0:
        return T == s
    # each zero gets a value >= 1, so the zeros must sum to T - s, which must be >= z
    return T - s >= z

